mapper.select:
SELECT id, session_id as sessionId, user_id as userId, skill_id as skillId, difficulty, resume_id as resumeId, resume_text as resumeText, jd_text as jdText, total_questions as totalQuestions, current_question_index as currentQuestionIndex, status, evaluate_status as evaluateStatus, evaluate_error as evaluateError, overall_score as overallScore, overall_feedback as overallFeedback, strengths, improvements, category_scores as categoryScores, source_type as sourceType, knowledge_base_id as knowledgeBaseId, interview_category as interviewCategory, created_at::timestamp as createdAt, completed_at::timestamp as completedAt, updated_at::timestamp as updatedAt FROM interview_sessions WHERE user_id = #{userId}
AND resume_id = #{resumeId}
AND status IN ('CREATED', 'IN_PROGRESS') ORDER BY created_at DESC LIMIT 1

